package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class ExportInboxControllerTest {
    String actor="55000000-0000-4000-8000-000000000011",tenant="55000000-0000-4000-8000-000000000001",job="55000000-0000-4000-8000-000000000099";
    Instant at=Instant.parse("2026-10-14T06:00:00Z");PlatformRepository platform;ExportInboxRepository repository;AssetExportDownloadGrant grants;ExportInboxSupport support;ExportInboxController controller;
    ExportInboxRepository.Message message(long version,Instant read){return new ExportInboxRepository.Message(job,tenant,actor,1,4,"a".repeat(64),100,1,at,at.plusSeconds(900),version,read);}
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(ExportInboxRepository.class);grants=new AssetExportDownloadGrant(new byte[32]);support=new ExportInboxSupport(true,true,repository,new AssetExportPublicationSupport(true,mock(AssetExportObjectStore.class),grants));controller=new ExportInboxController(platform,support);when(repository.readinessProblems()).thenReturn(List.of());when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",1,true)));when(repository.list(any(),anyInt(),any(),any(),anyBoolean())).thenReturn(new ExportInboxRepository.Page(List.of(message(0,null)),false,1,at.plusSeconds(1)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(x->{((Runnable)x.getArgument(6)).run();return ((Supplier<?>)x.getArgument(7)).get();});}
    MockHttpServletRequest request(String method,String suffix,String body){var r=new MockHttpServletRequest(method,"/api/v1/my-export-messages"+suffix);r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","inbox-test");r.addHeader("Idempotency-Key","own-inbox-read");r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void listReconstructsOriginalExpiryWithoutStorageAccessOrNewGrant(){var result=data(controller.list(request("GET","","")));var item=(Map<?,?>)((List<?>)result.get("items")).get(0);String url=(String)item.get("content_url");grants.verify(message(0,null).binding(),url.substring(url.indexOf("grant=")+6),at.plusSeconds(1));assertEquals(at.plusSeconds(900),item.get("expires_at"));assertNull(item.get("read_at"));verify(platform,never()).audit(any(),any(),any(),any(),any(),any(),any(),any());}
    @Test void expiredMessageRetainsHistoryButReturnsNoLink(){when(repository.list(any(),anyInt(),any(),any(),anyBoolean())).thenReturn(new ExportInboxRepository.Page(List.of(message(1,at.plusSeconds(3))),false,0,at.plusSeconds(900)));var item=(Map<?,?>)((List<?>)data(controller.list(request("GET","",""))).get("items")).get(0);assertEquals("EXPIRED",item.get("link_status"));assertNull(item.get("content_url"));assertEquals(at.plusSeconds(900),item.get("expires_at"));}
    @Test void scopeMismatchNeverReturnsMessageOrLink(){var wrong=new ExportInboxRepository.Message(job,tenant,job,1,4,"a".repeat(64),100,1,at,at.plusSeconds(900),0,null);when(repository.list(any(),anyInt(),any(),any(),anyBoolean())).thenReturn(new ExportInboxRepository.Page(List.of(wrong),false,1,at));assertEquals(503,assertThrows(DomainException.class,()->controller.list(request("GET","",""))).status);}
    @Test void invalidPagingAndDuplicateQueryRejected(){for(String key:List.of("tenant_id","before_id","bad")){var r=request("GET","","");r.addParameter(key,job);assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);}for(String value:List.of("0","51","1.0","01")){var r=request("GET","","");r.addParameter("page_size",value);assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);}var dup=request("GET","","");dup.addParameter("unread_only","true","false");assertEquals(400,assertThrows(DomainException.class,()->controller.list(dup)).status);}
    @Test void explicitReadUsesProtectedIdempotentCommandAndReturnsOriginalReadReceipt(){when(repository.markRead(any(),eq(job),eq(0L))).thenReturn(message(1,at.plusSeconds(4)));var result=data(controller.read(job,request("POST","/"+job+"/read","{\"expected_version\":0}")));assertEquals(1L,result.get("version"));assertEquals(at.plusSeconds(4),result.get("read_at"));assertFalse(result.containsKey("content_url"));verify(repository).authorizeRead(any(),eq(job));}
    @Test void invalidWriteCannotOverrideOwnerOrExpiry(){for(String b:List.of("{}","{\"expected_version\":0.0}","{\"expected_version\":2}","{\"expected_version\":0,\"read_at\":null}","{\"expected_version\":0,\"expected_version\":0}"))assertEquals(400,assertThrows(DomainException.class,()->controller.read(job,request("POST","/"+job+"/read",b))).status);verify(repository,never()).markRead(any(),any(),anyLong());}
    @Test void disabledOrUnavailableStorageDoesNotReturnEmptySuccess(){var disabled=new ExportInboxController(platform,ExportInboxSupport.disabled());assertEquals(422,assertThrows(DomainException.class,()->disabled.list(request("GET","",""))).status);when(repository.readinessProblems()).thenReturn(List.of("EXPORT_INBOX_STRUCTURE_OR_GUARDS_UNAVAILABLE"));assertEquals(false,support.status().get("ready"));assertEquals(503,assertThrows(DomainException.class,()->controller.list(request("GET","",""))).status);verify(repository,never()).list(any(),anyInt(),any(),any(),anyBoolean());}
    @Test void customerInactiveAndAnonymousRequestsRejected(){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"viewer",1,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET","",""))).status);when(platform.membership(actor,tenant)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET","",""))).status);assertEquals(401,assertThrows(DomainException.class,()->controller.list(new MockHttpServletRequest())).status);}
    @Test void linksNeverGoIntoSharedCaches(){var response=new MockHttpServletResponse();controller.headers(response);assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals("no-referrer",response.getHeader("Referrer-Policy"));}
}
